#!/usr/bin/env python3
"""i18n — English translations of the game schema's German dial
descriptions (DISPLAY LAYER ONLY — game files are never touched).

The game documents every AI dial in German
(addondata/config/ai/properties.xml). This map lets the GUI and CLI show
English instead, without modifying any game file. Keys are the MD5 of
the German text as decoded by parse_schema (UTF-8 file); values are the
English translation. Unknown strings fall back to the original German
text. Engine behavior is unaffected.
"""
import hashlib

_CACHE = {}


def translate(desc):
    """Return the English description for a German schema text, or the
    original when unknown (display layer only — never edits game files).
    """
    if not desc:
        return desc
    h = hashlib.md5(desc.encode("utf-8")).hexdigest()
    if h in _CACHE:
        hit = _CACHE[h]
    else:
        EN = EN_TRANSLATIONS
        hit = EN.get(h) or desc
        _CACHE[h] = hit
    return hit


